import { clsx } from 'clsx'

type Props = { status: 'pending' | 'accepted' | 'declined' }

export function RoleBadge({ status }: Props) {
  return (
    <span
      className={clsx(
        'text-xs px-1.5 py-0.5 rounded',
        status === 'accepted' && 'bg-success/10 text-success',
        status === 'pending' && 'bg-warning/10 text-warning',
        status === 'declined' && 'bg-danger/10 text-danger',
      )}
    >
      {status}
    </span>
  )
}
